import * as C from './core.mjs';import * as DB from './db.mjs';
import * as Cloud from './cloud.mjs';
import * as Accounts from './accounts.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let P,projects=[],mode=localStorage.getItem('jbp-mode')||'pro',page='home',selected=null,linkFrom=null,filter='all',search='',history=[],future=[],saveTimer,saveChain=Promise.resolve(),playback=null,renderJob=null,exporting=false,uiBusy=false;
const icons={text:'▤',character:'♧',scene:'◫',prop:'◇',image:'▧',video:'▷',audio:'♫',output:'▣'};let cloudAccount=null,cloudList=[],cloudError='';let recording=null,requestingMic=false;let toastTimer;let uiRevision=0,preparingPlay=false;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function queueSave(){P.updated=Date.now();$('#saveStatus')&&($('#saveStatus').textContent='保存中…');clearTimeout(saveTimer);const copy=structuredClone(P);saveTimer=setTimeout(()=>{saveTimer=null;saveChain=saveChain.catch(()=>{}).then(()=>DB.put(copy)).then(()=>{$('#saveStatus')&&($('#saveStatus').textContent='已保存在此浏览器')}).catch(e=>toast('保存失败，请立即导出项目备份：'+e.message))},220)}
async function flush(){clearTimeout(saveTimer);saveTimer=null;await saveChain.catch(()=>{});await DB.put(structuredClone(P))}
function checkpoint(){history.push(structuredClone(P));if(history.length>25)history.shift();future=[]}
function change(fn,redraw=true){checkpoint();fn();queueSave();if(redraw)render()}
function button(label,act,attrs='',cls=''){return `<button data-act="${act}" ${attrs} class="${cls}">${label}</button>`}
function asset(id){return P.assets.find(a=>a.id===id)}function node(id){return P.nodes.find(n=>n.id===id)}
function openModal(html,wide=false){$('#modalBody').classList.toggle('wide-modal',wide);$('#modalBody').innerHTML=button('×','close','','modal-close')+html;$('#modal').style.display='flex';$('#modalBody').querySelector('input,textarea,select,button')?.focus()}
function close(){if(recording||requestingMic)return toast('请先停止录音');if(exporting)return toast('正在导出，请先停止导出');$('#modal').style.display='none';$('#modalBody').innerHTML=''}
function syncHeader(){$('#simpleBtn').classList.toggle('active',mode==='simple');$('#proBtn').classList.toggle('active',mode==='pro');$('#modeHint').textContent=mode==='simple'?'资产与视频 · 轻量创作':'剧本 · 画布 · 分镜 · 剪辑 · 导出';const nav=[['home','◫','项目空间'],['models','◈','模型中心'],['grok','✦','图片生成'],['cloud','☁','云端项目'],...(mode==='pro'?[['script','▤','剧本创作'],['shots','▧','分镜管理'],['canvas','⌘','节点画布']]:[]),['assets','♧','资产中心'],['video','▷','视频工作台'],...(mode==='pro'?[['editor','▣','剪辑时间线']]:[]),['tasks','◷','任务队列']];$('#nav').innerHTML=nav.map(([p,i,n])=>button(`${i} ${n}`,'page',`data-page="${p}"`,'nav '+(page===p?'on':''))).join('')+`<div class="aside-bottom"><span class="status">● 本地 + 云端工作台</span><br><small>真实媒体上传与编辑<br>${cloudAccount?'云端账号已登录':'模型服务待接入'}</small>${button('项目备份 ↗','export','','full')}${button('操作帮助','help','','full soft')}</div>`}
function stopPlayback(){if(playback){cancelAnimationFrame(playback.raf);for(const m of playback.media.values())if(m instanceof HTMLMediaElement){m.pause();m.removeAttribute('src');m.load()}playback.ctx?.close();playback=null}}
function render(){if(!P)return;uiRevision++;stopPlayback();if(renderJob){renderJob.cancelled=true;renderJob=null}syncHeader();$('#main').innerHTML=`<div class="toolbar"><input class="title-input" value="${E(P.title)}" data-field="title" aria-label="项目名称"><span class="badge">${mode==='pro'?'正式版':'精简版'} · 本地工作台</span><span class="spacer"></span><span id="saveStatus" class="floating-save">已保存在此浏览器</span>${button('↶','undo',history.length?'':'disabled')}${button('↷','redo',future.length?'':'disabled')}${button('☁ 云保存','cloud-save')}${button('保存','save')}</div>`;({home:homePage,models:()=>Accounts.renderModules(P),cloud:cloudPage,grok:grokPage,script:scriptPage,assets:assetsPage,canvas:canvasPage,shots:shotsPage,video:videoPage,editor:editorPage,tasks:tasksPage}[page]||homePage)()}
function goto(p){if(exporting)return toast('请等待导出完成');if(mode==='simple'&&['canvas','script','shots','editor'].includes(p))p='video';page=p;selected=null;linkFrom=null;render()}
function blankSeed(){let p=C.project('三星堆 · 三千年的回响');p.script='第一集\n1-1 夜 内 考古实验室\n人物：杜宇、张教授\n△灯光落在青铜面具上，杜宇缓缓伸手，指尖触碰面具。\n杜宇：你是不是，一直在等我？\n△面具的眼睛忽然亮起，远处传来女子的声音。\n郫瑶（画外）：三千年了，你终于回来了。';p.shots=C.parseScript(p.script);let a=C.node('text',30,60),b=C.node('character',320,40),c=C.node('scene',320,330),d=C.node('image',620,120),e=C.node('video',920,120);a.prompt=p.script;p.nodes=[a,b,c,d,e];C.connect(p,a.id,d.id);C.connect(p,b.id,d.id);C.connect(p,c.id,d.id);C.connect(p,d.id,e.id);return p}
async function boot(){try{projects=await DB.list();let id=localStorage.getItem('jbp-active');P=projects.find(p=>p.id===id)||projects[0];if(!P){P=blankSeed();try{const old=typeof Accounts!=='undefined'&&Accounts.current()?null:JSON.parse(localStorage.getItem('jbp-project'));if(old){P.title=old.title||P.title;P.script=old.script||P.script;P.shots=C.parseScript(P.script);P.nodes.find(n=>n.type==='text').prompt=P.script;for(const a of old.assets||[])if(a.src)P.assets.push({id:C.uid(),name:a.name,type:a.type||'角色',kind:'image',src:a.src,created:Date.now(),locked:false,tags:'',description:''})}}catch{}await DB.put(P);projects=[P]}for(const t of P.tasks)if(t.status==='running'||t.status==='queued')t.status='interrupted';localStorage.setItem('jbp-active',P.id);render();Cloud.me().then(r=>{cloudAccount=r.user;syncHeader();const avatar=$('.avatar');if(avatar){avatar.textContent=cloudAccount.name.slice(0,1);avatar.title=cloudAccount.email}}).catch(e=>cloudError=e.message)}catch(e){$('#main').innerHTML=`<div class="page"><h2>浏览器存储不可用</h2><p>${E(e.message)}</p><p>请使用允许 IndexedDB 的正常浏览器窗口打开。</p></div>`}}
function homePage(){const list=projects.map(p=>p.id===P.id?P:p).sort((a,b)=>b.updated-a.updated);$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="hero custom-hero"><small>YOUR NEXT STORY STARTS HERE</small><h1 style="margin-top:14px">好故事，值得被看见。</h1><p class="muted">从文字走向画面。两个工作模式，共用一套项目资产。</p><div class="row wrap">${button('＋ 新建项目','new-project','','primary')}${button('继续创作 →','page',`data-page="${mode==='pro'?'canvas':'video'}"`)}${button('导入项目','import')}${button('备份当前项目','export')}</div></div><div class="row"><h3>项目空间</h3><small>${list.length} 个项目 · 此浏览器保存</small></div><div class="asset-grid">${list.map(p=>`<div class="card"><small>${p.id===P.id?'● 当前项目':'LOCAL PROJECT'}</small><h3>${E(p.title)}</h3><p class="muted">${p.assets.length} 个资产 / ${p.shots.length} 个分镜 / ${p.clips.length} 个片段</p><small>${new Date(p.updated).toLocaleString('zh-CN')}</small><div class="row wrap" style="margin-top:18px">${button('打开','open-project',`data-id="${p.id}"`)}${button('复制','duplicate-project',`data-id="${p.id}"`)}${button('删除','delete-project',`data-id="${p.id}"`,'danger')}</div></div>`).join('')}</div><div class="notice">上传真实图片、视频和音频，可以编辑分镜、制作时间线预演、导出分镜图与字幕。AI 内容生成需另接模型服务；任务队列会明确显示“等待服务”，不会伪造完成结果。</div></div>`)}
function scriptPage(){let eps=P.episodes||[];$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row"><div><small>SCRIPT ROOM</small><h1>故事的第一步。</h1></div><span class="spacer"></span>${button('导入 TXT','import-script')}${button('导出剧本 TXT','export-script')}</div><div class="split"><section class="section"><div class="row wrap">${button('全文','episode-select',`data-id="all"`,'active')}${eps.map(e=>button(E(e.name),'episode-select',`data-id="${e.id}"`)).join('')}${button('＋ 分集','add-episode')}</div><div style="margin-top:16px"><textarea class="script-text" id="scriptEditor" data-field="script" placeholder="第1集\n1-1 日 内 客厅\n人物：…\n△动作描述\n人物：台词">${E(P.script)}</textarea></div><div class="row wrap" style="margin-top:16px">${button('拆解为分镜','parse-script','','primary')}${button('同步剧本节点','sync-script')}${button('创建 AI 写作任务','script-task')}${button('朗读 / 停止','read-script')}</div></section><section class="section"><h3>创作约束</h3><div class="field"><label>题材</label><input data-setting="genre" value="${E(P.settings.genre||'悬疑奇幻')}"></div><div class="field"><label>单集字数</label><input data-setting="words" value="${E(P.settings.words||'700–1000 字')}"></div><div class="field"><label>写作要求</label><textarea data-setting="writing">${E(P.settings.writing||'合并连续△动作；人物语言一致；每集结尾设置钩子。')}</textarea></div><div class="notice">拆解是本地规则解析：保留动作、台词及场景，不会凭空生成新故事。AI 写作会进入等待服务队列。</div></section></div></div>`)}
function assetOptions(kind='',value='',empty='不绑定'){return `<option value="">${empty}</option>`+P.assets.filter(a=>!kind||a.kind===kind).map(a=>`<option value="${a.id}" ${a.id===value?'selected':''}>${E(a.name)} · ${E(a.type)}</option>`).join('')}
function assetsPage(){let list=P.assets.filter(a=>(filter==='all'||a.type===filter||a.kind===filter)&&(!search||[a.name,a.tags,a.description].join(' ').toLowerCase().includes(search.toLowerCase())));$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row wrap"><div><small>ASSET LIBRARY</small><h1>每个角色，始终如一。</h1></div><span class="spacer"></span>${button('↑ 上传媒体','upload','','primary')}${button('＋ 资产生成任务','asset-task')}${button('对比候选图','compare-assets')}${button('录制配音','record-audio')}</div><div class="row wrap" style="margin:20px 0">${['all','角色','场景','道具','video','audio'].map(t=>button({all:'全部',video:'视频',audio:'音频'}[t]||t,'filter',`data-type="${t}"`,filter===t?'active':'')).join('')}<input class="search" placeholder="搜索名称、标签" id="assetSearch" value="${E(search)}" aria-label="搜索资产"></div><div class="asset-grid">${list.map(a=>`<article class="asset-card"><div class="asset-preview">${mediaHTML(a,true)}</div><h3>${E(a.name)} ${a.locked?'🔒':''}</h3>${a.kind==='image'?`<label class="row"><input class="compare-check" type="checkbox" value="${a.id}" style="width:auto"><small>选择对比</small></label>`:''}<small>${E(a.type)} · ${a.kind} ${a.width?`· ${a.width}×${a.height}`:''} ${a.duration?'· '+a.duration.toFixed(1)+'秒':''}</small><p class="tags">${E(a.tags||'未添加标签')}</p><div class="row wrap">${button('编辑','edit-asset',`data-id="${a.id}"`)}${button('→ 时间线','asset-timeline',`data-id="${a.id}"`)}${button('↓','download-asset',`data-id="${a.id}"`)}</div></article>`).join('')||'<div class="empty">还没有匹配的资产。上传自己的图片、视频或音频开始创作。</div>'}</div><div class="notice">角色锁定用于固定参考资产与提示词，防止本地编辑误改。跨镜头实际生成一致性还取决于接入模型的参考图能力。</div></div>`)}
function mediaHTML(a,controls=false){if(!a)return '';if(a.kind==='image')return `<img src="${a.src}" alt="${E(a.name)}" loading="lazy">`;if(a.kind==='video')return `<video src="${a.src}" ${controls?'controls':''} preload="metadata" playsinline></video>`;return `<audio src="${a.src}" ${controls?'controls':''} preload="metadata"></audio>`}
function editAsset(id){const a=asset(id);openModal(`<h2>编辑资产</h2><div class="asset-preview">${mediaHTML(a,true)}</div><div class="field"><label>名称</label><input id="assetName" value="${E(a.name)}" ${a.locked?'disabled':''}></div><div class="grid2 field"><div><label>类别</label><select id="assetType" ${a.locked?'disabled':''}>${['角色','场景','道具','分镜','视频','音频'].map(t=>`<option ${a.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label>标签</label><input id="assetTags" value="${E(a.tags)}" ${a.locked?'disabled':''}></div></div><div class="field"><label>固定描述 / 人物设定</label><textarea id="assetDesc" ${a.locked?'disabled':''}>${E(a.description)}</textarea></div><div class="row wrap" style="margin-top:18px">${button('保存','save-asset',`data-id="${id}"`,'primary')}${button(a.locked?'解除锁定':'锁定资产','lock-asset',`data-id="${id}"`)}${a.kind==='image'?button('裁剪 / 调色','image-edit',`data-id="${id}"`):a.kind==='video'?button('提取参考帧','video-frame',`data-id="${id}"`):''}${button('删除','delete-asset',`data-id="${id}" ${a.locked?'disabled':''}`,'danger')}</div>`)}
function shotsPage(){$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row wrap"><div><small>STORYBOARD ROOM</small><h1>让故事有镜头。</h1></div><span class="spacer"></span>${button('＋ 新分镜','new-shot')}${button('导出镜头表 CSV','shots-csv')}${button('导出分镜图 PNG','shots-png','','primary')}${button('打印 / 保存 PDF','shots-print')}</div><div class="row wrap">${button('推送到画布','shots-canvas')}${button('加入时间线','shots-timeline')}${button('批量生成任务','shots-tasks')}<small>${P.shots.length} 个分镜 · 无绑定图的镜头不会加入时间线</small></div><div>${P.shots.map((s,i)=>`<article class="shot"><div><div class="shot-thumb">${asset(s.assetId)?mediaHTML(asset(s.assetId)):'镜头 '+String(i+1).padStart(2,'0')}</div><small>${E(s.episode)} · ${E(s.scene)}</small></div><div><input data-shot="${s.id}" data-key="scene" value="${E(s.scene)}" aria-label="场景"><textarea data-shot="${s.id}" data-key="description" aria-label="画面描述">${E(s.description)}</textarea><textarea data-shot="${s.id}" data-key="dialogue" placeholder="台词" aria-label="台词">${E(s.dialogue)}</textarea><input data-shot="${s.id}" data-key="subtitle" value="${E(s.subtitle)}" placeholder="字幕" aria-label="字幕"><select data-shot="${s.id}" data-key="assetId" aria-label="参考图">${assetOptions('image',s.assetId,'绑定分镜图片')}</select></div><div class="shot-settings"><div class="field"><label>时长（秒）</label><input type="number" min=".5" max="60" step=".5" data-shot="${s.id}" data-key="duration" value="${s.duration}"></div><div class="field"><label>景别</label><select data-shot="${s.id}" data-key="size">${['远景','全景','中景','近景','特写'].map(t=>`<option ${s.size===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>运镜</label><select data-shot="${s.id}" data-key="camera">${['固定','推进','拉远','横移','跟拍','环绕'].map(t=>`<option ${s.camera===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="row wrap" style="margin-top:12px">${button('↑','move-shot',`data-id="${s.id}" data-dir="-1"`)}${button('↓','move-shot',`data-id="${s.id}" data-dir="1"`)}${button('删除','delete-shot',`data-id="${s.id}"`,'danger')}</div></div></article>`).join('')||'<div class="empty">在剧本页拆解分镜，或手动添加镜头。</div>'}</div></div>`)}
function canvasPage(){$('#main').insertAdjacentHTML('beforeend',`<div class="workspace canvas-workspace"><div class="board" id="board"><div class="canvas-tools">${button('＋ 节点','new-node')}${button('整理','arrange')}${button('－','zoom',`data-dir="-1"`)}<button data-act="reset-view" id="zoomLabel">${Math.round(P.view.zoom*100)}%</button>${button('＋','zoom',`data-dir="1"`)}${button('批量任务','workflow-run')}${button('取消连线','cancel-link')}${button('导出画布','canvas-export')}</div><div class="world" id="world"><svg id="wires" class="lines" width="8000" height="6000"></svg><div id="canvasNodes"></div></div><div id="connectTip" class="connect-tip hidden"></div><div class="mini-map" id="minimap"></div></div><section class="inspector" id="inspector"></section></div>`);drawCanvas();bindCanvas()}
function drawCanvas(){if(!$('#world'))return;$('#world').style.transform=`translate(${P.view.x}px,${P.view.y}px) scale(${P.view.zoom})`;$('#zoomLabel').textContent=Math.round(P.view.zoom*100)+'%';$('#canvasNodes').innerHTML=P.nodes.map(n=>{const a=asset(n.resultAssetId)||n.assetIds.map(asset).find(a=>a&&a.kind!=='audio');return `<article class="node ${selected===n.id?'selected':''} ${n.locked?'locked':''}" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="node-head" data-drag="${n.id}"><strong>${icons[n.type]} ${E(n.name)}</strong><span>${n.locked?'🔒':'⋮'}</span></div><button class="port input" data-act="connect-in" data-id="${n.id}" aria-label="连接输入"></button><button class="port ${linkFrom===n.id?'pending':''}" data-act="connect-out" data-id="${n.id}" aria-label="连接输出"></button>${a?`<div class="node-media">${mediaHTML(a)}</div>`:`<div class="placeholder">${icons[n.type]}</div>`}<div class="node-body">${E(n.prompt.slice(0,95)||'点击编辑提示词与参考资产')}</div><div class="node-foot"><span>${n.assetIds.length} 个参考资产</span><span>${n.type==='text'?'文本可传递':'就绪 / 待模型'}</span></div></article>`}).join('');drawWires();drawInspector();$('#connectTip').classList.toggle('hidden',!linkFrom);$('#connectTip').textContent='选择目标节点左侧圆点完成连接；Esc 取消';$('#minimap').innerHTML=P.nodes.map(n=>`<i class="mini-dot" style="left:${Math.max(0,Math.min(97,n.x/18))}px;top:${Math.max(0,Math.min(60,n.y/12))}px"></i>`).join('')}
function drawWires(){$('#wires').innerHTML=P.edges.map(e=>{let a=node(e.from),b=node(e.to);if(!a||!b)return '';let x=a.x+240,y=a.y+59,X=b.x,Y=b.y+59;let bend=Math.max(60,Math.abs(X-x)*.45);return `<path class="edge" data-edge="${e.id}" d="M${x} ${y} C${x+bend} ${y},${X-bend} ${Y},${X} ${Y}" stroke="#9bad68" stroke-width="2" fill="none"><title>点击删除连线</title></path>`}).join('')}
function drawInspector(){let n=node(selected);if(!n){$('#inspector').innerHTML=`<small>DIRECTOR PANEL</small><h3 style="margin-top:15px">创作画布</h3><p class="muted">点击节点编辑；拖动背景平移；滚轮缩放。</p><div class="notice">右侧圆点为输出，左侧圆点为输入。点击两端建立真实数据连接。点击连线可删除。</div><p class="muted">${P.nodes.length} 个节点 · ${P.edges.length} 条连接</p>${button('＋ 添加节点','new-node','','full primary')}${button('把分镜加入画布','shots-canvas','','full')}`;return}const data=C.inputs(P,n.id);$('#inspector').innerHTML=`<small>${E(C.TYPES[n.type])} NODE</small><div class="field"><label>节点名称</label><input data-node-field="name" value="${E(n.name)}" ${n.locked?'disabled':''}></div><div class="field"><label>提示词 / 文本</label><textarea data-node-field="prompt" ${n.locked?'disabled':''}>${E(n.prompt)}</textarea></div><div class="field"><label>本节点参考资产</label>${n.assetIds.map(id=>{let a=asset(id);return a?`<div class="asset-chip">${a.kind==='image'?`<img src="${a.src}">`:icons[a.kind]}<span class="grow">${E(a.name)}</span>${button('×','unbind-node',`data-id="${id}" ${n.locked?'disabled':''}`)}</div>`:''}).join('')}${button('＋ 绑定资产','bind-node',n.locked?'disabled':'','full')}</div>${['video','image'].includes(n.type)?`<div class="grid2 field"><div><label>时长（秒）</label><input data-node-param="duration" type="number" min="1" max="60" value="${n.params.duration}" ${n.locked?'disabled':''}></div><div><label>画幅</label><select data-node-param="ratio" ${n.locked?'disabled':''}>${['16:9','9:16','1:1'].map(v=>`<option ${n.params.ratio===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>首帧 / 尾帧</label><select data-node-param="firstFrame" ${n.locked?'disabled':''}>${assetOptions('image',n.params.firstFrame,'选择首帧')}</select><select data-node-param="lastFrame" style="margin-top:7px" ${n.locked?'disabled':''}>${assetOptions('image',n.params.lastFrame,'选择尾帧')}</select></div>`:''}<div class="field"><label>上游输入</label><small>${data.nodes.length-1} 个上游节点 · ${data.assets.length} 个合并参考</small>${button('查看输入数据','inspect-input','','full')}</div><div class="row wrap" style="margin-top:18px">${button(n.locked?'解锁':'锁定','lock-node')}${button('复制','duplicate-node')}${button('删除','delete-node',n.locked?'disabled':'','danger')}</div>${button(n.type==='output'?'打开合成时间线':'创建生成任务','node-task','','full primary')}`}
function bindCanvas(){const b=$('#board');b.onpointerdown=e=>{if(e.button!==0)return;const drag=e.target.closest('[data-drag]');if(drag){let n=node(drag.dataset.drag);selected=n.id;drawInspector();$$('.node').forEach(el=>el.classList.toggle('selected',el.dataset.node===n.id));if(n.locked)return;checkpoint();const sx=e.clientX,sy=e.clientY,ox=n.x,oy=n.y;drag.setPointerCapture(e.pointerId);drag.onpointermove=ev=>{n.x=Math.max(0,ox+(ev.clientX-sx)/P.view.zoom);n.y=Math.max(0,oy+(ev.clientY-sy)/P.view.zoom);let el=drag.parentElement;el.style.left=n.x+'px';el.style.top=n.y+'px';drawWires()};drag.onpointerup=drag.onpointercancel=()=>{drag.onpointermove=null;queueSave()};return}if(e.target.closest('button,.node,.edge,.canvas-tools'))return;const x=e.clientX,y=e.clientY,ox=P.view.x,oy=P.view.y;b.setPointerCapture(e.pointerId);b.onpointermove=v=>{P.view.x=ox+v.clientX-x;P.view.y=oy+v.clientY-y;$('#world').style.transform=`translate(${P.view.x}px,${P.view.y}px) scale(${P.view.zoom})`};b.onpointerup=b.onpointercancel=()=>{b.onpointermove=null;queueSave()}};const wheel=e=>{if(e.target.closest('.inspector'))return;e.preventDefault();const r=b.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,z=P.view.zoom,nz=Math.max(.25,Math.min(2,z*(e.deltaY<0?1.08:.92)));P.view.x=x-(x-P.view.x)*nz/z;P.view.y=y-(y-P.view.y)*nz/z;P.view.zoom=nz;$('#world').style.transform=`translate(${P.view.x}px,${P.view.y}px) scale(${nz})`;$('#zoomLabel').textContent=Math.round(nz*100)+'%';queueSave()};b.addEventListener('wheel',wheel,{passive:false})}
function videoPage(){$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="hero custom-hero"><small>VIDEO LAB</small><h1 style="margin-top:14px">让画面，开始讲故事。</h1><p class="muted">绑定真实资产、首尾帧和角色设定；上传完成的视频进入时间线。</p></div><div class="split"><section class="section"><h3>参考素材</h3><div class="asset-grid">${P.assets.filter(a=>a.kind==='image').map(a=>`<label class="asset-card"><div class="asset-preview">${mediaHTML(a)}</div><div class="row" style="margin-top:12px"><input type="checkbox" class="video-ref" value="${a.id}" style="width:auto" ${(P.settings.videoRefs||[]).includes(a.id)?'checked':''}><span>${E(a.name)} ${a.locked?'🔒':''}</span></div></label>`).join('')||'<div class="empty">先上传角色、场景或首帧图片。</div>'}</div><div class="row wrap" style="margin-top:16px">${button('上传媒体','upload')}${button('打开素材库','page',`data-page="assets"`)}</div><h3 style="margin-top:30px">已有视频</h3><div class="asset-grid">${P.assets.filter(a=>a.kind==='video').map(a=>`<div class="asset-card"><div class="asset-preview">${mediaHTML(a,true)}</div><h3>${E(a.name)}</h3>${button('加入时间线','asset-timeline',`data-id="${a.id}"`)}</div>`).join('')||'<small class="muted">暂无视频，接入生成服务或上传自己的素材。</small>'}</div>${mode==='simple'?button('预演与导出','simple-editor','','full'):''}</section><section class="section"><h3>视频任务参数</h3><div class="field"><label>生成方式</label><select data-setting="videoMethod">${['图生视频','首尾帧','多参考图','文生视频'].map(t=>`<option ${P.settings.videoMethod===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>提示词</label><textarea id="videoPrompt" data-setting="videoPrompt">${E(P.settings.videoPrompt||'')}</textarea></div><div class="grid2 field"><div><label>时长（秒）</label><input type="number" min="1" max="60" data-setting="videoDuration" value="${P.settings.videoDuration||5}"></div><div><label>画幅</label><select data-setting="videoRatio">${['16:9','9:16','1:1'].map(t=>`<option ${P.settings.videoRatio===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label>首帧</label><select data-setting="firstFrame">${assetOptions('image',P.settings.firstFrame)}</select></div><div class="field"><label>尾帧</label><select data-setting="lastFrame">${assetOptions('image',P.settings.lastFrame)}</select></div><div class="field"><label>批量数量</label><input id="batchCount" type="number" min="1" max="20" value="1"></div>${button('创建视频任务','video-task','','primary full')}<div class="notice">任务提交、输入快照、取消、重试、导出请求包已实现。未连接模型时任务停在“等待服务”，不会显示虚假视频。</div></section></div></div>`)}
function task(kind,data){return {id:C.uid(),kind,name:data.name||kind,status:'blocked',created:Date.now(),data:structuredClone(data),error:'尚未接入模型服务',resultAssetId:''}}
function tasksPage(){$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row"><div><small>JOB CENTER</small><h1>每一次创作，都有记录。</h1></div><span class="spacer"></span>${button('导出全部请求包','tasks-export')}${button('清理已取消','tasks-clear')}</div>${P.tasks.length?`<table class="line-table"><thead><tr><th>任务</th><th>创建时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${P.tasks.map(t=>`<tr><td><strong>${E(t.name)}</strong><br><small>${E(t.kind)}</small></td><td>${new Date(t.created).toLocaleString('zh-CN')}</td><td class="status-${t.status}">${{blocked:'等待服务接入',completed:'已有真实结果',cancelled:'已取消',interrupted:'运行中断',failed:'失败',running:'处理中'}[t.status]||t.status}</td><td><div class="row wrap">${button('详情','task-detail',`data-id="${t.id}"`)}${button('绑定结果','task-result',`data-id="${t.id}"`)}${button('重试','task-retry',`data-id="${t.id}"`)}${button('取消','task-cancel',`data-id="${t.id}" ${['completed','cancelled'].includes(t.status)?'disabled':''}`)}</div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无任务。在画布或视频页创建任务。</div>'}<div class="notice">可以为任务绑定已上传的真实结果，进入分镜与剪辑工作流。请求包包含模型所需的提示词、媒体引用、首尾帧和参数，可供后续接入。</div></div>`)}
function addClip(a,opts={}){let c={id:C.uid(),assetId:a.id,name:a.name,track:a.kind==='audio'?'audio':'video',duration:a.kind==='image'?5:Math.min(a.duration||5,600),trimStart:0,start:0,volume:1,subtitle:'',motion:'固定',...opts};P.clips.push(c);return c}
function editorPage(){$('#main').insertAdjacentHTML('beforeend',`<div class="page"><div class="row wrap"><div><small>EDITING ROOM</small><h1>把镜头，连成故事。</h1></div><span class="spacer"></span>${button('＋ 加入媒体','timeline-add')}${button('导出预演视频','export-video','','primary')}${button('导出剪辑清单','timeline-json')}</div><div class="split"><section><canvas class="preview-canvas" id="previewCanvas" width="${P.settings.width}" height="${P.settings.height}"></canvas><div class="row wrap" style="margin-top:12px">${button('▷ 播放','play',`id="playBtn"`)}${button('↤','seek-start')}<small id="playTime">0.0 / ${C.duration(P).toFixed(1)} 秒</small><span class="spacer"></span><select id="projectRatio" style="width:150px" data-setting="ratio">${['16:9','9:16','1:1'].map(r=>`<option ${P.settings.ratio===r?'selected':''}>${r}</option>`).join('')}</select></div><input type="range" id="seek" class="timeline-slider" min="0" max="${Math.max(.01,C.duration(P))}" step=".01" value="0" aria-label="时间线位置"><section class="section"><div class="row"><strong>画面轨</strong><small>拖动卡片排序 · 点击剪辑参数</small></div><div class="clip-list" data-track="video">${clipCards('video')}</div><strong>音频轨</strong><div class="clip-list" data-track="audio">${clipCards('audio')}</div></section><section class="section"><div class="row wrap"><h3 style="margin:0">字幕编辑</h3>${button('＋ 字幕','subtitle-add')}${button('从片段同步','subtitle-sync')}${button('导入 SRT / VTT','subtitle-import')}${button('字幕样式','subtitle-style')}${button('SRT','subtitle-export',`data-type="srt"`)}${button('VTT','subtitle-export',`data-type="vtt"`)}</div><div style="margin-top:16px">${P.subtitles.map(s=>`<div class="subtitle-row"><input type="number" min="0" step=".1" data-subtitle="${s.id}" data-key="start" value="${s.start}" aria-label="字幕开始秒"><input type="number" min=".1" step=".1" data-subtitle="${s.id}" data-key="end" value="${s.end}" aria-label="字幕结束秒"><input data-subtitle="${s.id}" data-key="text" value="${E(s.text)}" aria-label="字幕内容">${button('×','subtitle-delete',`data-id="${s.id}"`)}</div>`).join('')||'<p class="muted">暂无字幕。</p>'}</div></section></section><section class="section" id="clipInspector"><h3>片段参数</h3><p class="muted">选择画面或音频片段进行编辑。</p><div class="notice">图片可用推进、拉远、横移制作动态预演；视频可裁切入点与时长；音频支持起始位置和音量。导出在浏览器中实时合成 WebM，不需要 API。</div></section></div></div>`);$$('.timeline-clip').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.id);el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain'),from=P.clips.findIndex(c=>c.id===id),to=P.clips.findIndex(c=>c.id===el.dataset.id);if(from<0||to<0||P.clips[from].track!==P.clips[to].track)return;change(()=>{const [c]=P.clips.splice(from,1);P.clips.splice(to,0,c)});toast('片段已排序；字幕可点击“从片段同步”重新对齐')}});$('#seek').oninput=()=>previewAt(+$('#seek').value);previewAt(0);if(selected&&P.clips.some(c=>c.id===selected))clipInspector(selected)}
function clipCards(track){return P.clips.filter(c=>c.track===track).map(c=>`<div class="timeline-clip ${track==='audio'?'audio-track':''} ${selected===c.id?'selected':''}" draggable="true" data-act="clip-select" data-id="${c.id}" style="width:${Math.max(120,Math.min(250,c.duration*15))}px"><strong>${E(c.name)}</strong><br><small>${c.duration.toFixed(1)}秒 ${track==='audio'?'· 起始 '+c.start+'秒':''}</small></div>`).join('')||'<div class="muted">从资产中心加入媒体，或从分镜批量推送。</div>'}
function clipInspector(id){selected=id;const c=P.clips.find(c=>c.id===id);if(!c)return;$$('.timeline-clip').forEach(e=>e.classList.toggle('selected',e.dataset.id===id));const a=asset(c.assetId);$('#clipInspector').innerHTML=`<h3>${E(c.name)}</h3><div class="asset-preview">${mediaHTML(a,true)}</div><div class="field"><label>名称</label><input data-clip="${id}" data-key="name" value="${E(c.name)}"></div><div class="field"><label>时长（秒）</label><input data-clip="${id}" data-key="duration" type="number" min=".1" max="600" step=".1" value="${c.duration}"></div>${a?.kind!=='image'?`<div class="field"><label>素材入点（秒）</label><input data-clip="${id}" data-key="trimStart" type="number" min="0" step=".1" value="${c.trimStart}"></div><div class="field"><label>音量（0–1）</label><input data-clip="${id}" data-key="volume" type="number" min="0" max="1" step=".1" value="${c.volume}"></div>`:`<div class="field"><label>图片动态预演</label><select data-clip="${id}" data-key="motion">${['固定','推进','拉远','横移'].map(t=>`<option ${t===c.motion?'selected':''}>${t}</option>`).join('')}</select></div>`}${c.track==='audio'?`<div class="field"><label>时间线起始（秒）</label><input data-clip="${id}" data-key="start" type="number" min="0" step=".1" value="${c.start}"></div><div class="grid2 field"><div><label>淡入秒数</label><input type="number" min="0" max="10" step=".1" data-clip="${id}" data-key="fadeIn" value="${c.fadeIn||0}"></div><div><label>淡出秒数</label><input type="number" min="0" max="10" step=".1" data-clip="${id}" data-key="fadeOut" value="${c.fadeOut||0}"></div></div>`:`<div class="field"><label>片段字幕</label><textarea data-clip="${id}" data-key="subtitle">${E(c.subtitle)}</textarea></div>`}<div class="row wrap" style="margin-top:20px">${button('复制','clip-duplicate',`data-id="${id}"`)}${button('切分','clip-split',`data-id="${id}"`)}${button('删除','clip-delete',`data-id="${id}"`,'danger')}</div>`}
async function loadImage(src){return new Promise((res,rej)=>{let i=new Image;i.onload=()=>res(i);i.onerror=()=>rej(Error('图片无法解码'));i.src=src})}
async function mediaCache(){const m=new Map();const used=[...new Set(P.clips.map(c=>c.assetId))];for(const id of used){const a=asset(id);if(!a)throw Error('时间线引用的素材不存在');if(a.kind==='image')m.set(id,await loadImage(a.src));else{const v=document.createElement(a.kind==='video'?'video':'audio');v.preload='auto';v.playsInline=true;v.src=a.src;await new Promise((res,rej)=>{const timer=setTimeout(()=>rej(Error('媒体载入超时：'+a.name)),10000);v.onloadeddata=()=>{clearTimeout(timer);res()};v.onerror=()=>{clearTimeout(timer);rej(Error(a.name+' 无法解码'))};if(v.readyState>=2){clearTimeout(timer);res()}});m.set(id,v)}}return m}
function paint(canvas,t,media){const ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height;ctx.fillStyle='#080c10';ctx.fillRect(0,0,W,H);const ac=C.activeClip(P,t);if(ac){const c=ac.clip,a=asset(c.assetId),m=media.get(c.assetId);if(m&&a&&((a.kind==='image')||(m.readyState>=2))){let iw=m.naturalWidth||m.videoWidth,ih=m.naturalHeight||m.videoHeight;if(iw&&ih){let scale=Math.min(W/iw,H/ih);let f=ac.local/c.duration;if(c.motion==='推进')scale*=1+f*.12;if(c.motion==='拉远')scale*=1.12-f*.12;let w=iw*scale,h=ih*scale,x=(W-w)/2,y=(H-h)/2;if(c.motion==='横移'){w*=1.15;h*=1.15;x=(W-w)/2+(f-.5)*W*.1;y=(H-h)/2}ctx.drawImage(m,x,y,w,h)}}}else{ctx.fillStyle='#829675';ctx.font=`${W/35}px sans-serif`;ctx.textAlign='center';ctx.fillText(P.clips.length?'播放结束':'加入图片或视频开始预演',W/2,H/2)}const subs=P.subtitles.filter(s=>t>=s.start&&t<s.end).map(s=>s.text).join('\n');if(subs){const style=P.settings.subtitleStyle||{};ctx.font=`${Math.round(H*(Number(style.scale)||.0435))}px sans-serif`;ctx.textAlign='center';const lines=wrapText(ctx,subs,W*.86);const lh=H/17;let y=H-lh*(lines.length+.5)-(Number(style.bottom)||0)*H;ctx.fillStyle=style.background===false?'transparent':'#000a';ctx.fillRect(W*.04,y-lh*.8,W*.92,lh*(lines.length+.5));ctx.fillStyle=/^#[0-9a-fA-F]{6}$/.test(style.color)?style.color:'#ffffff';for(const l of lines){ctx.fillText(l,W/2,y);y+=lh}}}
function wrapText(ctx,str,max){const result=[];for(const line of str.split('\n')){let part='';for(const char of line){if(ctx.measureText(part+char).width>max&&part){result.push(part);part=char}else part+=char}if(part)result.push(part)}return result}
async function previewAt(t){stopPlayback();const canvas=$('#previewCanvas');if(!canvas)return;if(renderJob)renderJob.cancelled=true;const token={cancelled:false};renderJob=token;try{let media=await mediaCache();if(token.cancelled||!canvas.isConnected)return;const ac=C.activeClip(P,t);if(ac){const m=media.get(ac.clip.assetId);if(m instanceof HTMLMediaElement){await seekMedia(m,ac.clip.trimStart+ac.local)}}if(token.cancelled)return;paint(canvas,t,media);$('#playTime').textContent=`${t.toFixed(1)} / ${C.duration(P).toFixed(1)} 秒`;for(const m of media.values())if(m instanceof HTMLMediaElement){m.pause();m.removeAttribute('src');m.load()}}catch(e){toast(e.message)}}
function seekMedia(m,t){const at=Math.min(Math.max(0,t),Math.max(0,(Number.isFinite(m.duration)?m.duration:0)-.04));return new Promise((resolve,reject)=>{if(Math.abs(m.currentTime-at)<.03)return resolve();const timer=setTimeout(()=>{m.removeEventListener('seeked',done);reject(Error('媒体定位超时'))},5000);function done(){clearTimeout(timer);resolve()}m.addEventListener('seeked',done,{once:true});m.currentTime=at})}
function syncMedia(t,media,outputs){const ac=C.activeClip(P,t);for(const c of P.clips){const m=media.get(c.id)||media.get(c.assetId);if(!(m instanceof HTMLMediaElement))continue;let local=c.track==='audio'?t-c.start:ac?.clip.id===c.id?ac.local:-1;const active=local>=0&&local<c.duration;let vol=c.volume;if(active&&c.fadeIn)vol*=Math.min(1,local/c.fadeIn);if(active&&c.fadeOut)vol*=Math.min(1,(c.duration-local)/c.fadeOut);vol=Math.max(0,Math.min(1,vol));if(outputs&&outputs.has(c.id))outputs.get(c.id).gain.value=active?vol:0;else m.volume=vol;if(active){if(Math.abs(m.currentTime-(c.trimStart+local))>.3)m.currentTime=c.trimStart+local;if(m.paused)m.play().catch(()=>{})}else m.pause()}}
async function playbackCache(){const map=new Map();for(const c of P.clips){let a=asset(c.assetId);if(!a)throw Error('片段缺少素材');if(a.kind==='image'){if(!map.has(a.id))map.set(a.id,await loadImage(a.src));continue}let v=document.createElement(a.kind==='video'?'video':'audio');v.src=a.src;v.preload='auto';v.playsInline=true;await new Promise((res,rej)=>{const timer=setTimeout(()=>rej(Error('媒体载入超时：'+a.name)),10000);v.onloadeddata=()=>{clearTimeout(timer);res()};v.onerror=()=>{clearTimeout(timer);rej(Error('素材无法解码：'+a.name))};if(v.readyState>=2){clearTimeout(timer);res()}});map.set(c.id,v)}return map}
function frameMedia(cache,t){let map=new Map(cache),ac=C.activeClip(P,t);if(ac&&cache.has(ac.clip.id))map.set(ac.clip.assetId,cache.get(ac.clip.id));return map}
async function play(){if(preparingPlay)return;if(renderJob){renderJob.cancelled=true;renderJob=null}if(playback){const at=+$('#seek').value;stopPlayback();$('#playBtn').textContent='▷ 播放';return previewAt(at)}let total=C.duration(P);if(!total)return toast('请先加入画面片段');preparingPlay=true;const revision=uiRevision;let media;try{media=await playbackCache()}finally{preparingPlay=false}if(revision!==uiRevision){for(const m of media.values())if(m instanceof HTMLMediaElement){m.pause();m.removeAttribute('src');m.load()}return}let start=+$('#seek').value;if(start>=total)start=0;let time=performance.now();playback={media,raf:0};$('#playBtn').textContent='Ⅱ 暂停';function tick(){if(!playback)return;let t=Math.min(total,start+(performance.now()-time)/1000);syncMedia(t,media);paint($('#previewCanvas'),t,frameMedia(media,t));$('#seek').value=t;$('#playTime').textContent=`${t.toFixed(1)} / ${total.toFixed(1)} 秒`;if(t>=total){stopPlayback();$('#playBtn').textContent='▷ 播放';return}playback.raf=requestAnimationFrame(tick)}tick()}
async function exportVideo(){let total=C.duration(P);if(!total)return toast('请先加入画面片段');if(total>600)return toast('本地导出单次支持 10 分钟，请拆分项目');if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)return toast('当前浏览器不支持本地视频合成，请使用桌面版 Chrome / Edge');openModal(`<h2>导出预演视频</h2><p class="muted">合成图片、视频、音轨和烧录字幕。导出需要实时播放 ${total.toFixed(1)} 秒，请保持页面前台。</p><div class="notice">输出格式为浏览器支持的 WebM；这是用现有素材制作的预演，不是 AI 生成新视频。需要 MP4 时可用剪辑软件转换。</div><progress id="exportProgress" max="1" value="0" style="width:100%"></progress><p id="exportText">准备开始</p>${button('开始导出','export-start','','full primary')}${button('停止','export-stop','','full')}`)}
let exportStop=false;
async function runExport(){if(exporting)return;exporting=true;exportStop=false;$('#modalBody button[data-act="export-start"]').disabled=true;stopPlayback();const snapshot=P;let stream,rec,ctx,cache,raf,visibility;try{cache=await playbackCache();if(exportStop)throw Error('已停止导出');const canvas=document.createElement('canvas');canvas.width=P.settings.width;canvas.height=P.settings.height;const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw Error('当前浏览器没有可用的 WebM 编码器');stream=canvas.captureStream(P.settings.fps||24);let gains=new Map();if([...cache.values()].some(m=>m instanceof HTMLMediaElement)){ctx=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();const dest=ctx.createMediaStreamDestination();for(const c of P.clips){let m=cache.get(c.id);if(m instanceof HTMLMediaElement){const source=ctx.createMediaElementSource(m),gain=ctx.createGain();source.connect(gain);gain.connect(dest);gain.gain.value=0;gains.set(c.id,gain)}}stream.addTrack(dest.stream.getAudioTracks()[0])}rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5000000});const chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};const stopped=new Promise((res,rej)=>{rec.onstop=res;rec.onerror=e=>rej(e.error||Error('编码失败'))});let total=C.duration(P);paint(canvas,0,frameMedia(cache,0));syncMedia(0,cache,gains);await Promise.all([...cache.values()].filter(m=>m instanceof HTMLMediaElement&&!m.paused).map(m=>m.play().catch(()=>{throw Error('音视频播放被浏览器阻止')})));rec.start(500);const begin=performance.now();visibility=()=>{if(document.hidden){exportStop=true;$('#exportText').textContent='页面切到后台，已停止导出，请保持前台重试'}};document.addEventListener('visibilitychange',visibility);await new Promise(resolve=>{const tick=()=>{const t=Math.min(total,(performance.now()-begin)/1000);if(exportStop||t>=total){resolve();return}syncMedia(t,cache,gains);paint(canvas,t,frameMedia(cache,t));$('#exportProgress').value=t/total;$('#exportText').textContent=`合成中 ${Math.round(t/total*100)}% · ${t.toFixed(1)} / ${total.toFixed(1)} 秒`;raf=requestAnimationFrame(tick)};tick()});rec.stop();await stopped;if(!exportStop){download(new Blob(chunks,{type:mime}),'jubaopeng-preview.webm');$('#exportProgress').value=1;$('#exportText').textContent='导出完成：已下载真实合成视频';toast('预演视频已导出')}else $('#exportText').textContent='导出已停止，没有保存不完整成片'}catch(e){$('#exportText').textContent='导出失败：'+e.message;toast(e.message)}finally{cancelAnimationFrame(raf);document.removeEventListener('visibilitychange',visibility);stream?.getTracks().forEach(t=>t.stop());if(rec?.state==='recording')rec.stop();if(cache)for(const m of cache.values())if(m instanceof HTMLMediaElement){m.pause();m.removeAttribute('src');m.load()}await ctx?.close();P=snapshot;exporting=false;$('#modalBody button[data-act="export-start"]')&&($('#modalBody button[data-act="export-start"]').disabled=false)}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function downloadJSON(value,name){download(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),name)}
function textFile(accept,fn){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{if(input.files[0])try{await fn(await input.files[0].text())}catch(e){toast(e.message)}};input.click()}
function taskModal(kind){openModal(`<h2>${E(kind)}生成任务</h2><div class="field"><label>名称</label><input id="taskName" placeholder="输入名称"></div><div class="field"><label>描述 / 提示词</label><textarea id="taskPrompt"></textarea></div><div class="field"><label>参考资产</label><select id="taskAsset">${assetOptions('')}</select></div><div class="notice">任务将保存完整输入并等待服务接入。现在不调用 API。</div>${button('创建任务','create-generic-task',`data-kind="${kind}"`,'primary full')}`)}
async function shotsPNG(){if(!P.shots.length)return toast('暂无分镜');if(P.shots.length>100)return toast('分镜图单次最多导出 100 镜头，请拆分项目');toast('正在制作分镜图…');const W=1200,cellW=380,cellH=365,cols=3,rows=Math.ceil(P.shots.length/cols),canvas=document.createElement('canvas');canvas.width=W;canvas.height=80+rows*cellH;let ctx=canvas.getContext('2d');ctx.fillStyle='#10151c';ctx.fillRect(0,0,W,canvas.height);ctx.fillStyle='#e9f0df';ctx.font='28px sans-serif';ctx.fillText(P.title.slice(0,45),25,48);for(let i=0;i<P.shots.length;i++){const s=P.shots[i],x=20+(i%cols)*395,y=80+Math.floor(i/cols)*cellH;ctx.fillStyle='#232d33';ctx.fillRect(x,y,cellW,210);const a=asset(s.assetId);if(a?.kind==='image'){const image=await loadImage(a.src);let scale=Math.min(cellW/image.width,210/image.height);ctx.drawImage(image,x+(cellW-image.width*scale)/2,y+(210-image.height*scale)/2,image.width*scale,image.height*scale)}ctx.fillStyle='#d9fc6d';ctx.font='18px sans-serif';ctx.fillText(`镜头 ${i+1} · ${s.size} · ${s.camera} · ${s.duration}s`,x,y+238);ctx.fillStyle='#c8d0d7';ctx.font='16px sans-serif';let lines=wrapText(ctx,s.description,cellW);lines.slice(0,4).forEach((l,j)=>ctx.fillText(l,x,y+264+j*22))}canvas.toBlob(b=>{if(b)download(b,'jubaopeng-storyboard.png');else toast('图片导出失败，请减少镜头数量')},'image/png')}
function imageEdit(id){const a=asset(id);openModal(`<h2>裁剪与调色 · 另存新资产</h2><div class="asset-preview" style="height:230px"><img id="editPreview" src="${a.src}"></div><div class="grid2 field"><div><label>画幅</label><select id="cropRatio"><option>原始</option><option>16:9</option><option>9:16</option><option>1:1</option></select></div><div><label>亮度</label><input id="brightness" type="range" min=".5" max="1.5" step=".05" value="1"></div><div><label>对比度</label><input id="contrast" type="range" min=".5" max="1.5" step=".05" value="1"></div><div><label>饱和度</label><input id="saturation" type="range" min="0" max="2" step=".1" value="1"></div></div><small>按所选画幅居中裁剪，原图保持不变。</small>${button('另存新图片','image-save',`data-id="${id}"`,'primary full')}`);['brightness','contrast','saturation'].forEach(k=>$('#'+k).oninput=()=>{$('#editPreview').style.filter=`brightness(${$('#brightness').value}) contrast(${$('#contrast').value}) saturate(${$('#saturation').value})`})}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
async function importMedia(files){if(uiBusy)return;uiBusy=true;const projectId=P.id;checkpoint();try{for(const f of files){if(P.id!==projectId)break;if(f.size>50*1024*1024){toast(f.name+' 超过 50MB，暂不支持');continue}let kind=f.type.split('/')[0];if(!['image','video','audio'].includes(kind)||!/^((image\/(png|jpeg|webp|gif))|(video\/(mp4|webm|quicktime))|(audio\/(mpeg|mp3|wav|x-wav|ogg|webm|mp4|x-m4a|m4a|aac|flac)))$/i.test(f.type)){toast('不支持的文件：'+f.name);continue}toast('正在导入 '+f.name);let src=await new Promise((res,rej)=>{let r=new FileReader;r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(f)});let a={id:C.uid(),name:f.name,kind,type:kind==='image'?'角色':kind==='video'?'视频':'音频',src,created:Date.now(),locked:false,tags:'',description:''};if(kind==='image'){let im=await loadImage(src);a.width=im.width;a.height=im.height}else{let el=document.createElement(kind);el.src=src;await new Promise((res,rej)=>{const timer=setTimeout(()=>rej(Error(f.name+' 读取超时')),10000);el.onloadedmetadata=()=>{clearTimeout(timer);res()};el.onerror=()=>{clearTimeout(timer);rej(Error(f.name+' 无法解码'))}});a.duration=Number.isFinite(el.duration)?el.duration:5;if(kind==='video'){a.width=el.videoWidth;a.height=el.videoHeight}el.removeAttribute('src');el.load()}P.assets.push(a);queueSave()}await flush();render();toast('媒体已导入当前项目')}catch(e){toast('部分媒体导入失败：'+e.message);queueSave();render()}finally{uiBusy=false}}
