'confirm-delete-asset':e=>{let id=e.dataset.id;change(()=>{P.assets=P.assets.filter(a=>a.id!==id);for(const n of P.nodes){n.assetIds=n.assetIds.filter(v=>v!==id);if(n.resultAssetId===id)n.resultAssetId='';for(const k of ['firstFrame','lastFrame'])if(n.params[k]===id)n.params[k]=''}P.shots.forEach(s=>{if(s.assetId===id)s.assetId=''});P.clips=P.clips.filter(c=>c.assetId!==id);C.rebuildSubtitles(P);for(const t of P.tasks)if(t.resultAssetId===id){t.resultAssetId='';t.status='blocked'}P.settings.videoRefs=(P.settings.videoRefs||[]).filter(v=>v!==id);for(const k of ['firstFrame','lastFrame'])if(P.settings[k]===id)P.settings[k]=''});close()},
