'image-save':async e=>{const a=asset(e.dataset.id),im=await loadImage(a.src),ratio=$('#cropRatio').value;let w=im.width,h=im.height;if(ratio!=='原始'){let [rw,rh]=ratio.split(':').map(Number);if(w/h>rw/rh)w=h*rw/rh;else h=w*rh/rw}const canvas=document.createElement('canvas');const max=Math.min(1,2048/Math.max(w,h));canvas.width=Math.round(w*max);canvas.height=Math.round(h*max);let ctx=canvas.getContext('2d');ctx.filter=`brightness(${$('#brightness').value}) contrast(${$('#contrast').value}) saturate(${$('#saturation').value})`;ctx.drawImage(im,(im.width-w)/2,(im.height-h)/2,w,h,0,0,canvas.width,canvas.height);change(()=>P.assets.push({...a,id:C.uid(),name:a.name+' · 调整版',locked:false,src:canvas.toDataURL('image/png'),width:canvas.width,height:canvas.height,created:Date.now()}));close();toast('新图片已保存为资产')},
